import * as THREE from 'three'

/** Merge coincident vertices and re-index — smooths hard creases on extruded text. */
export function mergeVertices(geometry, tolerance = 1e-4) {
  const positions = geometry.attributes.position.array
  const vertexCount = positions.length / 3
  const attrs = geometry.attributes
  const attrNames = Object.keys(attrs)

  const hashToIndex = {}
  const newPositions = []
  const newIndices = []
  const newAttrArrays = {}
  attrNames.forEach(name => {
    if (name !== 'position') newAttrArrays[name] = []
  })

  const round = v => Math.round(v / tolerance)

  for (let vi = 0; vi < vertexCount; vi++) {
    const x = positions[vi * 3]
    const y = positions[vi * 3 + 1]
    const z = positions[vi * 3 + 2]
    const key = `${round(x)}|${round(y)}|${round(z)}`

    let target
    if (hashToIndex[key] === undefined) {
      target = newPositions.length / 3
      hashToIndex[key] = target
      newPositions.push(x, y, z)
      attrNames.forEach(name => {
        if (name === 'position') return
        const arr = attrs[name].array
        const itemSize = attrs[name].itemSize
        for (let k = 0; k < itemSize; k++) {
          newAttrArrays[name].push(arr[vi * itemSize + k])
        }
      })
    } else {
      target = hashToIndex[key]
    }
    newIndices.push(target)
  }

  const merged = geometry.clone()
  merged.setIndex(newIndices)
  merged.setAttribute('position', new THREE.BufferAttribute(new Float32Array(newPositions), 3))
  attrNames.forEach(name => {
    if (name === 'position') return
    const itemSize = attrs[name].itemSize
    merged.setAttribute(name, new THREE.BufferAttribute(new Float32Array(newAttrArrays[name]), itemSize))
  })
  merged.computeVertexNormals()
  return merged
}

// Lazy THREE ref — set before use from MascotText
mergeVertices.THREE = null

export function mergeVerticesWithThree(THREE, geometry, tolerance = 1e-4) {
  if (!geometry?.attributes?.position) return geometry
  const positions = geometry.attributes.position.array
  const vertexCount = positions.length / 3
  const attrs = geometry.attributes
  const attrNames = Object.keys(attrs)

  const hashToIndex = {}
  const newPositions = []
  const newIndices = []
  const newAttrArrays = {}
  attrNames.forEach(name => {
    if (name !== 'position') newAttrArrays[name] = []
  })

  const round = v => Math.round(v / tolerance)

  for (let vi = 0; vi < vertexCount; vi++) {
    const x = positions[vi * 3]
    const y = positions[vi * 3 + 1]
    const z = positions[vi * 3 + 2]
    const key = `${round(x)}|${round(y)}|${round(z)}`

    let target
    if (hashToIndex[key] === undefined) {
      target = newPositions.length / 3
      hashToIndex[key] = target
      newPositions.push(x, y, z)
      attrNames.forEach(name => {
        if (name === 'position') return
        const arr = attrs[name].array
        const itemSize = attrs[name].itemSize
        for (let k = 0; k < itemSize; k++) {
          newAttrArrays[name].push(arr[vi * itemSize + k])
        }
      })
    } else {
      target = hashToIndex[key]
    }
    newIndices.push(target)
  }

  const merged = new THREE.BufferGeometry()
  merged.setIndex(newIndices)
  merged.setAttribute('position', new THREE.BufferAttribute(new Float32Array(newPositions), 3))
  attrNames.forEach(name => {
    if (name === 'position') return
    const itemSize = attrs[name].itemSize
    merged.setAttribute(name, new THREE.BufferAttribute(new Float32Array(newAttrArrays[name]), itemSize))
  })
  merged.computeVertexNormals()
  return merged
}
