import React, { useRef } from 'react'
import { useFrame } from 'react-three-fiber'
import lerp from 'lerp'

/** World-space pan only — rotation is applied inside Mascot around geometry centre. */
export default function MascotInspect({ inspectRef, children }) {
  const panRef = useRef()
  const smooth = useRef({ posX: 0, posY: 0 })

  useFrame(() => {
    if (!panRef.current || !inspectRef?.current) return
    const t = inspectRef.current

    if (t.snap) {
      smooth.current.posX = t.posX ?? 0
      smooth.current.posY = t.posY ?? 0
    } else if (!t.enabled) {
      smooth.current.posX = lerp(smooth.current.posX, 0, 0.12)
      smooth.current.posY = lerp(smooth.current.posY, 0, 0.12)
    } else {
      smooth.current.posX = lerp(smooth.current.posX, t.posX ?? 0, 0.22)
      smooth.current.posY = lerp(smooth.current.posY, t.posY ?? 0, 0.22)
    }

    panRef.current.position.set(smooth.current.posX, smooth.current.posY, 0)
  })

  return <group ref={panRef}>{children}</group>
}
